def write(name, cols, rows):
    for r in rows: assert len(r) == len(cols), (name, r[0], len(r), len(cols))
    with open(H / name, "w", encoding="utf-8", newline="") as f:
        w = csv.writer(f, delimiter="\t", lineterminator="\n"); w.writerow(cols); w.writerows(rows)

def main():
    write("hypotheses.tsv", HYP_COLS, HYP); write("tools_roles.tsv", ROLE_COLS, ROLES)
    write("experiment_ladder.tsv", LAD_COLS, LAD); write("outcome_matrix.tsv", OUT_COLS, OUT)
    print("ok")
if __name__ == "__main__":
    if len(sys.argv) > 1: print(__doc__)
    else: main()
